import 'package:cloud_firestore/cloud_firestore.dart'; import 'package:firebase_core/firebase_core.dart'; import 'package:flutter/material.dart'; void main() async { WidgetsFlutterBinding.ensureInitialized(); await Firebase.initializeApp(); final superDocs = await FirebaseFirestore.instance.collection('supervisores').get(); print('Supervisors count: ' + superDocs.docs.length.toString()); for(var d in superDocs.docs) { print('Supervisor ID: ' + d.id); } final idososDocs = await FirebaseFirestore.instance.collection('idoso_perfil').get(); print('Idosos Profiles count: ' + idososDocs.docs.length.toString()); for(var d in idososDocs.docs) { print('Idoso ID: ' + d.id + ', SupervisorId: ' + d.data()['supervisorId'].toString() + ', Status: ' + d.data()['status'].toString()); final lembretes = await FirebaseFirestore.instance.collection('lembretes').where('idosoId', isEqualTo: d.id).get(); print('  -> Lembretes count: ' + lembretes.docs.length.toString()); } }
